{"policy":"permit (
    principal is User,
    action == Action::"signArtifact",
    resource is Artifact
)
when {
    principal.roles.contains(Role::"committer") &&
    resource.builtBy == principal &&
    resource.buildSucceeded &&
    resource.status == "built" &&
    resource.buildTags.contains("production-release") &&
    context.sourceNetworkIsCorporateVpn
};

forbid (
    principal is User,
    action == Action::"signArtifact",
    resource is Artifact
)
when {
    principal.roles.contains(Role::"committer") &&
    resource.builtBy != principal
};"}
